function normalizePatientProfile(raw: { patient: Patient; appointments?: Array<Record<string, unknown>>; prescriptions?: Array<Record<string, unknown>>; reports?: Array<Record<string, unknown>>; labOrders?: Array<Record<string, unknown>>; dispatchHistory?: Array<Record<string, unknown>> }): PatientProfile {
  const appointments = raw.appointments || []
  const visits: PatientVisit[] = appointments.map((visit) => ({ id: String(visit.id), visit_date: String(visit.appointment_date || ''), appointment_time: visit.appointment_time ? String(visit.appointment_time) : undefined, provider: String(visit.provider || 'Clinic team'), visit_type: String(visit.appointment_type || 'Dental visit'), status: String(visit.status || 'scheduled'), summary: String(visit.reason || visit.notes || 'Visit recorded.'), procedures: Array.isArray(visit.procedures) ? visit.procedures as string[] : [], is_appointment: true }))
  const patient = { ...raw.patient, last_visit: raw.patient.last_visit || visits.filter((visit) => visit.status === 'completed').map((visit) => visit.visit_date).sort().at(-1) || null, next_appointment: raw.patient.next_appointment || visits.filter((visit) => !['cancelled', 'completed'].includes(visit.status) && visit.visit_date >= today).map((visit) => visit.visit_date).sort()[0] || null }
  const prescriptions: PatientPrescription[] = (raw.prescriptions || []).map((item) => ({ id: String(item.id), patient_id: String(item.patient_id || patient.id), medication: String(item.medication || item.medication_name || ''), dosage: String(item.dosage || ''), frequency: String(item.frequency || ''), duration: String(item.duration || ''), instructions: String(item.instructions || 'Use as directed.'), prescribed_at: String(item.prescribed_at || item.created_at || ''), prescribed_by: String(item.prescribed_by || 'Clinic team') }))
  const reports: PatientMedicalReport[] = (raw.reports || []).map((item) => ({ id: String(item.id), patient_id: String(item.patient_id || patient.id), file_name: String(item.file_name || item.attachment_name || 'Clinical report'), mime_type: String(item.mime_type || item.attachment_mime_type || 'application/octet-stream'), file_size: Number(item.file_size || item.attachment_size || 0), data_base64: String(item.data_base64 || ''), description: item.description ? String(item.description) : undefined, uploaded_at: String(item.uploaded_at || item.created_at || ''), uploaded_by: String(item.uploaded_by || 'Clinic team') }))
  const normalizeDispatch = (item: Record<string, unknown>): PatientDispatchRecord => ({ id: String(item.id), lab_order_id: String(item.lab_order_id || ''), channel: item.recipient_type === 'patient' ? 'patient' : item.recipient_type === 'clinic' ? 'clinic' : 'lab', recipient: String(item.recipient || ''), status: ['sent', 'processing'].includes(String(item.status)) ? 'provider-ready' : 'queued', created_at: String(item.created_at || ''), note: item.note ? String(item.note) : `Queued via ${String(item.channel || 'provider')} for provider processing.` })
  const allDispatches = (raw.dispatchHistory || []).map(normalizeDispatch)
  const lab_orders: PatientLabOrder[] = (raw.labOrders || []).map((item) => { const dispatch_history = Array.isArray(item.dispatch_history) ? (item.dispatch_history as Array<Record<string, unknown>>).map(normalizeDispatch) : allDispatches.filter((dispatch) => dispatch.lab_order_id === String(item.id)); return { id: String(item.id), patient_id: String(item.patient_id || patient.id), order_number: String(item.order_number || `LAB-${String(item.id).slice(0, 8)}`), ordered_at: String(item.ordered_at || item.created_at || ''), tests: String(item.tests || item.test_name || ''), teeth_creation_service: String(item.teeth_creation_service || ''), lab_name: String(item.lab_name || ''), lab_email: String(item.lab_email || ''), lab_phone: String(item.lab_phone || ''), instructions: String(item.instructions || ''), copy_to_patient: Boolean(item.copy_to_patient ?? true), copy_to_clinic: Boolean(item.copy_to_clinic ?? false), dispatch_status: item.dispatch_status === 'provider-ready' || item.status === 'processing' ? 'provider-ready' : 'queued', dispatch_note: String(item.dispatch_note || 'Queued for provider processing; delivery status is traceable in Dispatch history.'), dispatch_history } })
  return { patient, visits, prescriptions, reports, lab_orders, dispatch_history: allDispatches }
}

function makeLabOrderPdf(input: { orderNumber: string; patientId: string; tests: string; teethService: string; labName: string; instructions: string }) {
  const safe = (value: string) => value.replace(/[^\x20-\x7E]/g, '?').replace(/[()\\]/g, (character) => `\\${character}`)
  const lines = [`Dental laboratory order`, `Order: ${input.orderNumber}`, `Patient ID: ${input.patientId}`, `Lab: ${input.labName}`, `Tests: ${input.tests}`, `Teeth service: ${input.teethService || 'Not specified'}`, `Instructions: ${input.instructions || 'None provided'}`]
  const stream = [`BT`, `/F1 16 Tf`, `50 760 Td`, `(${safe(lines[0])}) Tj`, `/F1 10 Tf`, ...lines.slice(1).map((line) => `0 -28 Td (${safe(line)}) Tj`), `ET`, ''].join('\n')
  const objects = [`<< /Type /Catalog /Pages 2 0 R >>`, `<< /Type /Pages /Kids [3 0 R] /Count 1 >>`, `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>`, `<< /Length ${stream.length} >>\nstream\n${stream}endstream`, `<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>`]
  let pdf = '%PDF-1.4\n'; const offsets = [0]
  objects.forEach((object, index) => { offsets.push(pdf.length); pdf += `${index + 1} 0 obj\n${object}\nendobj\n` })
  const xref = pdf.length; pdf += `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n${offsets.slice(1).map((offset) => `${String(offset).padStart(10, '0')} 00000 n \n`).join('')}trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF\n`
  return { base64: btoa(pdf), size: new TextEncoder().encode(pdf).length }
}

function makePaymentReportPdf(input: { clinicName: string; generatedAt: string; summary: PaymentSummary; payments: Payment[] }) {
  const safe = (value: string) => value.replace(/[^\x20-\x7E]/g, '?').replace(/[()\\]/g, (character) => `\\${character}`)
  const currency = input.payments[0]?.currency || 'INR'
  const amount = (value: number) => `${currency} ${Number(value || 0).toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`
  const lines = [
    `Payment report - ${input.clinicName}`,
    `Generated: ${input.generatedAt}`,
    `Total payments: ${input.summary.total_payments}   Customers: ${input.summary.customers_count}`,
    `Collected: ${amount(input.summary.collected_amount)}   Pending: ${amount(input.summary.pending_amount)}   Refunded: ${amount(input.summary.refunded_amount)}`,
    ``,
    `Payment ID              Customer ID           Customer            Status     Amount`,
    ...input.payments.slice(0, 30).map((payment) => `${payment.payment_number.padEnd(22).slice(0, 22)}  ${payment.customer_id.slice(0, 18).padEnd(18)}  ${`${payment.first_name} ${payment.last_name}`.slice(0, 18).padEnd(18)}  ${payment.status.padEnd(9)}  ${amount(payment.amount)}`),
  ]
  const stream = [`BT`, `/F1 14 Tf`, `40 770 Td`, `(${safe(lines[0])}) Tj`, `/F1 8 Tf`, ...lines.slice(1).map((line) => `0 -18 Td (${safe(line)}) Tj`), `ET`, ''].join('\n')
  const objects = [`<< /Type /Catalog /Pages 2 0 R >>`, `<< /Type /Pages /Kids [3 0 R] /Count 1 >>`, `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>`, `<< /Length ${stream.length} >>\nstream\n${stream}endstream`, `<< /Type /Font /Subtype /Type1 /BaseFont /Courier >>`]
  let pdf = '%PDF-1.4\n'; const offsets = [0]
  objects.forEach((object, index) => { offsets.push(pdf.length); pdf += `${index + 1} 0 obj\n${object}\nendobj\n` })
  const xref = pdf.length; pdf += `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n${offsets.slice(1).map((offset) => `${String(offset).padStart(10, '0')} 00000 n \n`).join('')}trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF\n`
  return { base64: btoa(pdf), size: new TextEncoder().encode(pdf).length }
}

