  const sampleDispatch: PatientDispatchRecord = { id: `demo-dispatch-${index + 1}`, lab_order_id: `demo-lab-order-${index + 1}`, channel: 'lab', recipient: 'BrightSmile Dental Lab', status: 'provider-ready', created_at: createdAt, note: 'Prepared for provider handoff; no external delivery was attempted.' }
